mapper.select:
SELECT SANCTIONS_ID, USER_ID, SANCTIONS_TYPES, SANCTIONS_START_DATE, SANCTIONS_END_DATE, SANCTIONS_REASON, ADMIN_ACCOUNT_ID, SANCTIONS_CREATED_AT
FROM sanctions
WHERE SANCTIONS_ID = #{param1}

SELECT SANCTIONS_ID, USER_ID, SANCTIONS_TYPES, SANCTIONS_START_DATE, SANCTIONS_END_DATE, SANCTIONS_REASON, ADMIN_ACCOUNT_ID, SANCTIONS_CREATED_AT
FROM sanctions


        AND USER_ID = #{userId}


        AND SANCTIONS_TYPES = #{sanctionsTypes}


        AND SANCTIONS_REASON LIKE CONCAT('%', #{sanctionsReason}, '%')


        AND ADMIN_ACCOUNT_ID = #{adminAccountId}



        AND (
        (SANCTIONS_START_DATE BETWEEN #{searchStartDate} AND #{searchEndDate}) OR
        (SANCTIONS_END_DATE BETWEEN #{searchStartDate} AND #{searchEndDate}) OR
        (SANCTIONS_CREATED_AT BETWEEN #{searchStartDate} AND #{searchEndDate})
        )


        AND (
        SANCTIONS_START_DATE >= #{searchStartDate} OR
        SANCTIONS_END_DATE >= #{searchStartDate} OR
        SANCTIONS_CREATED_AT >= #{searchStartDate}
        )


        AND (
        SANCTIONS_START_DATE <= #{searchEndDate} OR
        SANCTIONS_END_DATE <= #{searchEndDate} OR
        SANCTIONS_CREATED_AT <= #{searchEndDate}
        )



        AND DATEDIFF(SANCTIONS_END_DATE, SANCTIONS_START_DATE) BETWEEN #{durationMin} AND #{durationMax}


        AND DATEDIFF(SANCTIONS_END_DATE, SANCTIONS_START_DATE) >= #{durationMin}


        AND DATEDIFF(SANCTIONS_END_DATE, SANCTIONS_START_DATE) <= #{durationMax}
